    if (backupGate) return backupGate;
    const isolationGate = writerIsolationErrorResult(
      "diviops_tb_layout_update",
      { content }
    );
    if (isolationGate) return isolationGate;
    const body = { content };
    if (dry_run) body.dry_run = true;
