    const result = await authoringWrite(`/theme-builder/layout/update/${layout_id}`, "PUT", body, "tb_layout_update", dry_run === true);
    return {
      content: [
        { type: "text", text: serializeEnvelope(result, "diviops_tb_layout_update") }
      ]
    };
