function ensureScfWpCli() {
  if (!wpCli) {
    withCode(
      "scf.not_configured",
      "WP-CLI not configured.",
      "Set WP_PATH (Local by Flywheel auto-detect) or WP_CLI_CMD (containerized wrappers) to enable SCF round-trip tools."
    );
  }
  return wpCli;
}
function pushScfFlag(args, name, value) {
  if (!value) return;
  args.push(`--${name}=${value}`);
}
function failScfCommand(result, args) {
  const detail = result.error ?? "wp-cli command failed";
  const kind = result.failureKind ?? "exited";
  let message;
  let hint;
  let stderrForData;
  if (kind === "rejected") {
    message = detail;
    hint = "Command was rejected before execution. Common causes: not in the allowlist (see DIVIOPS_WP_CLI_ALLOW for opt-ins) or filesystem path outside DIVIOPS_WP_CLI_SAFE_FS_ROOT.";
    stderrForData = detail;
  } else if (kind === "spawn_failed") {
    message = `wp-cli could not spawn: ${detail}`;
    hint = "The OS refused to start the wp-cli executable \u2014 common causes: WP_CLI_CMD points at a missing binary (ENOENT), the binary is not executable (EACCES), or PATH does not include wp-cli. Verify `which wp` (or your WP_CLI_CMD prefix) resolves and is executable. error.data.stdout / error.data.stderr are empty because the child never ran.";
    stderrForData = detail;
  } else if (kind === "killed") {
    message = `wp-cli command terminated: ${detail}`;
    hint = "Command was launched but killed before it finished (timeout or signal). error.data.stdout / error.data.stderr carry whatever streamed before the kill. Consider raising the timeout or splitting the command into smaller batches.";
    stderrForData = result.stderr;
  } else {
    message = `wp-cli exited with code ${result.exitCode}`;
    hint = "Inspect error.data.stderr for the failure reason; re-run with WP_CLI_DEBUG=1 in the env to surface PHP traceback.";
    stderrForData = result.stderr;
  }
  withCode("scf.command_failed", message, hint, {
    exit_code: result.exitCode,
    stdout: result.stdout,
    stderr: stderrForData,
    failure_kind: kind,
    command: [...args]
  });
}
